package com.zerotrust.internalresource.service;
import com.zerotrust.internalresource.dto.*;import com.zerotrust.internalresource.entity.FileResourceEntity;import com.zerotrust.internalresource.repository.FileResourceRepository;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.List;
@Service public class FileResourceService{public static final String RESOURCE_ID="internal-files";private final FileResourceRepository repository;public FileResourceService(FileResourceRepository repository){this.repository=repository;}public List<FileResourceResponse> findAll(){return repository.findAll().stream().map(FileResourceResponse::from).toList();}public FileResourceResponse findById(Long id){return FileResourceResponse.from(entity(id));}public FileResourceResponse create(FileResourceRequest request){var entity=new FileResourceEntity();entity.setResourceId(RESOURCE_ID);apply(entity,request);var now=Instant.now();entity.setCreatedAt(now);entity.setUpdatedAt(now);return FileResourceResponse.from(repository.save(entity));}public FileResourceResponse update(Long id,FileResourceRequest request){var entity=entity(id);apply(entity,request);entity.setUpdatedAt(Instant.now());return FileResourceResponse.from(repository.save(entity));}public void delete(Long id){repository.delete(entity(id));}private FileResourceEntity entity(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("file resource not found: "+id));}private void apply(FileResourceEntity e,FileResourceRequest r){e.setName(r.name());e.setDescription(r.description());e.setCategory(r.category());e.setOwner(r.owner());e.setDepartment(r.department());e.setClassificationLevel(r.classificationLevel());e.setStatus(r.status());}}
